const email = $json.body?.email || $json.email || '';
const message = $json.body?.message || $json.message || '';

const cleanEmail = String(email).trim().toLowerCase();
const cleanMessage = String(message).trim();

if (!cleanEmail) {
  throw new Error('Email obligatoire.');
}

if (!cleanMessage) {
  throw new Error('Message obligatoire.');
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(cleanEmail)) {
  throw new Error('Adresse email invalide.');
}

const ticketId = `JAPPO-${new Date().getFullYear()}-${Date.now().toString().slice(-6)}`;

return [{
  json: {
    email: cleanEmail,
    message: cleanMessage,
    ticketId,
    receivedAt: new Date().toISOString()
  }
}];

