const original = $('Préparer + Ticket').item.json;

const content = $json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('Réponse OpenRouter vide ou invalide.');
}

let ai;

try {
  ai = typeof content === 'string' ? JSON.parse(content) : content;
} catch (error) {
  throw new Error(`Impossible de parser la réponse IA : ${content}`);
}

return [{
  json: {
    ticketId: original.ticketId,
    email: original.email,
    message: original.message,
    receivedAt: original.receivedAt,
    category: ai.category || 'autre',
    priority: ai.priority || 'MEDIUM',
    resolved: Boolean(ai.resolved),
    needsHuman: Boolean(ai.needsHuman),
    response: ai.response || '',
    reason: ai.reason || ''
  }
}];

const data = $json;

const forcedHumanCategories = [
  'paiement',
  'remboursement',
  'securite',
  'bug'
];

const forcedHuman = forcedHumanCategories.includes(data.category);

const needsHuman = forcedHuman || data.needsHuman || !data.resolved;

let priority = data.priority;

if (forcedHuman && priority === 'LOW') {
  priority = 'HIGH';
}

if (data.category === 'paiement' || data.category === 'remboursement' || data.category === 'securite') {
  priority = 'HIGH';
}

return [{
  json: {
    ...data,
    priority,
    needsHuman,
    status: needsHuman ? 'OPEN' : 'RESOLVED'
  }
}];

